#include <bits/stdc++.h>
using namespace std;
int main(){int r,c;cin>>r>>c;vector<string>a(r);for(auto&s:a)cin>>s;int n=r*c,S=-1,T=-1;vector<vector<int>>g(n),rev(n);int di[]={-1,1,0,0},dj[]={0,0,-1,1};for(int i=0;i<r;i++)for(int j=0;j<c;j++){int u=i*c+j;char z=a[i][j];if(z=='S')S=u;if(z=='T')T=u;if(z=='#')continue;for(int d=0;d<4;d++){if(z=='-'&&d<2)continue;if(z=='|'&&d>=2)continue;if(z=='.'&&d!=1)continue;int x=i+di[d],y=j+dj[d];if(x>=0&&x<r&&y>=0&&y<c&&a[x][y]!='#'){int v=x*c+y;g[u].push_back(v);rev[v].push_back(u);}}}auto visit=[&](int start,const vector<vector<int>>&edges){vector<int>v(n);queue<int>q;q.push(start);v[start]=1;while(!q.empty()){int u=q.front();q.pop();for(int w:edges[u])if(!v[w]){v[w]=1;q.push(w);}}return v;};auto reachable=visit(S,g);if(!reachable[T]){cout<<"I'm stuck!\n";return 0;}auto reachesTarget=visit(T,rev);int ans=0;for(int i=0;i<n;i++)ans+=reachable[i]&&!reachesTarget[i];cout<<ans<<'\n';}
